mapper.select:
SELECT sn.notice_id, sn.notice_title, sn.is_top, sn.notice_level, sn.notice_content, sn.create_time, nu.is_read, nu.read_time, d.dept_name, snt.notice_type_name FROM sys_notice_user nu,sys_notice sn,sys_notice_type snt,sys_department d
nu.notice_id=sn.notice_id AND sn.notice_type_id=snt.notice_type_id AND sn.dept_id=d.dept_id AND nu.user_id = #{userId}
AND sn.notice_title LIKE CONCAT('%',#{noticeTitle},'%')
AND nu.is_read=#{isRead}
